<script setup lang="ts">
import { computed, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { channels, rateKeys, cashRates, type CalculationInput } from '../types'
import { useApp } from '../stores/app'
import Icon from './Icon.vue'
const props = defineProps<{ input: CalculationInput }>(); const { t } = useI18n(); const app = useApp(); const channel = ref('shelf'); const open = ref(false)
const effective = computed(() => { const rates = { ...app.settings?.channels[channel.value] }; const sources: Record<string,string> = {}; rateKeys.forEach(k => sources[k] = 'preset'); const ret = app.settings?.categoryReturns[props.input.category]; if (ret) { rates.returns = ret; sources.returns = 'categoryDefault' } for (const [k,v] of Object.entries(props.input.overrides?.[channel.value] || {})) { rates[k] = v; sources[k] = 'override' } return { rates, sources } })
function set(k: string, event: Event) { const v = (event.target as HTMLInputElement).value; props.input.overrides ||= {}; props.input.overrides[channel.value] ||= {}; if (v === '') delete props.input.overrides[channel.value][k]; else props.input.overrides[channel.value][k] = v; if (!Object.keys(props.input.overrides[channel.value]).length) delete props.input.overrides[channel.value] }
</script>
<template><section class="panel rate-editor"><button class="disclosure-heading" @click="open = !open"><div><h3>{{ t('assumptions') }}</h3><p>{{ t('assumptionsSub') }}</p></div><Icon name="chevron" :class="{ turn: open }" /></button><template v-if="open"><div class="channel-tabs"><button v-for="c in channels" :key="c" :class="{ chosen: channel === c }" @click="channel = c">{{ t(c) }}</button></div><div class="form-grid rates-grid"><div v-for="k in rateKeys" :key="k" class="field"><label>{{ t(k) }} <span>{{ cashRates.includes(k) ? 'Rp' : '%' }}</span></label><input type="number" min="0" :max="cashRates.includes(k) ? 1000000000000 : 100" step="any" :value="input.overrides?.[channel]?.[k] ?? ''" :placeholder="effective.rates[k]" :aria-label="`${t(channel)} ${t(k)}`" @input="set(k, $event)" /><small :class="{ 'override-source': effective.sources[k] === 'override' }">{{ t(effective.sources[k]) }} · {{ effective.rates[k] }}</small></div></div><button class="text-link reset-link" @click="delete input.overrides[channel]"><Icon name="refresh" :size="15" />{{ t('reset') }}</button></template></section></template>
